import Foundation

struct WeatherResponse: Decodable {
    let latitude: Double
    let longitude: Double
    let timezone: String
    let current: CurrentWeather
    let hourly: HourlyWeather
    let daily: DailyWeather
}

struct CurrentWeather: Decodable {
    let time: String
    let temperature2m: Double
    let apparentTemperature: Double
    let relativeHumidity2m: Int
    let precipitation: Double
    let weatherCode: Int
    let windSpeed10m: Double

    enum CodingKeys: String, CodingKey {
        case time
        case temperature2m = "temperature_2m"
        case apparentTemperature = "apparent_temperature"
        case relativeHumidity2m = "relative_humidity_2m"
        case precipitation
        case weatherCode = "weather_code"
        case windSpeed10m = "wind_speed_10m"
    }
}

struct HourlyWeather: Decodable {
    let time: [String]
    let temperature2m: [Double]
    let weatherCode: [Int]
    let precipitationProbability: [Int]

    enum CodingKeys: String, CodingKey {
        case time
        case temperature2m = "temperature_2m"
        case weatherCode = "weather_code"
        case precipitationProbability = "precipitation_probability"
    }
}

struct DailyWeather: Decodable {
    let time: [String]
    let weatherCode: [Int]
    let temperature2mMax: [Double]
    let temperature2mMin: [Double]
    let sunrise: [String]
    let sunset: [String]
    let precipitationProbabilityMax: [Int]

    enum CodingKeys: String, CodingKey {
        case time
        case weatherCode = "weather_code"
        case temperature2mMax = "temperature_2m_max"
        case temperature2mMin = "temperature_2m_min"
        case sunrise, sunset
        case precipitationProbabilityMax = "precipitation_probability_max"
    }
}

struct PlaceSearchResponse: Decodable { let results: [PlaceResult]? }

struct PlaceResult: Decodable, Identifiable, Hashable {
    let id: Int
    let name: String
    let latitude: Double
    let longitude: Double
    let country: String?
    let admin1: String?
    var subtitle: String { [admin1, country].compactMap { $0 }.joined(separator: ", ") }
}

struct HourForecast: Identifiable {
    let id = UUID(); let date: Date; let temperature: Double; let code: Int; let rainChance: Int
}
struct DayForecast: Identifiable {
    let id = UUID(); let date: Date; let code: Int; let high: Double; let low: Double; let rainChance: Int
}

enum WeatherKind { case clear, cloudy, fog, drizzle, rain, snow, storm }

struct WeatherPresentation {
    let title: String
    let symbol: String
    let kind: WeatherKind
    static func from(code: Int, isDay: Bool = true) -> WeatherPresentation {
        switch code {
        case 0: return .init(title: "Ясно", symbol: isDay ? "sun.max.fill" : "moon.stars.fill", kind: .clear)
        case 1, 2: return .init(title: code == 1 ? "Преимущественно ясно" : "Переменная облачность", symbol: isDay ? "cloud.sun.fill" : "cloud.moon.fill", kind: .cloudy)
        case 3: return .init(title: "Пасмурно", symbol: "cloud.fill", kind: .cloudy)
        case 45, 48: return .init(title: "Туман", symbol: "cloud.fog.fill", kind: .fog)
        case 51, 53, 55, 56, 57: return .init(title: "Морось", symbol: "cloud.drizzle.fill", kind: .drizzle)
        case 61, 63, 65, 66, 67, 80, 81, 82: return .init(title: "Дождь", symbol: "cloud.rain.fill", kind: .rain)
        case 71, 73, 75, 77, 85, 86: return .init(title: "Снег", symbol: "cloud.snow.fill", kind: .snow)
        case 95, 96, 99: return .init(title: "Гроза", symbol: "cloud.bolt.rain.fill", kind: .storm)
        default: return .init(title: "Погода", symbol: "cloud.fill", kind: .cloudy)
        }
    }
}

enum WeatherDate {
    static let isoLocal: DateFormatter = { let f = DateFormatter(); f.locale = Locale(identifier: "en_US_POSIX"); f.dateFormat = "yyyy-MM-dd'T'HH:mm"; return f }()
    static let day: DateFormatter = { let f = DateFormatter(); f.locale = Locale(identifier: "en_US_POSIX"); f.dateFormat = "yyyy-MM-dd"; return f }()
}
