cat > WeatherFlow/WeatherService.swift <<'SWIFT'
import Foundation

enum WeatherServiceError: LocalizedError {
    case invalidURL, invalidResponse
    var errorDescription: String? {
        switch self {
        case .invalidURL: return "Не удалось сформировать адрес запроса."
        case .invalidResponse: return "Сервис погоды вернул некорректный ответ."
        }
    }
}

struct WeatherService {
    private let session: URLSession = .shared
    func fetchWeather(latitude: Double, longitude: Double) async throws -> WeatherResponse {
        var c = URLComponents(string: "https://api.open-meteo.com/v1/forecast")
        c?.queryItems = [
            .init(name: "latitude", value: String(latitude)), .init(name: "longitude", value: String(longitude)),
            .init(name: "current", value: "temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,weather_code,wind_speed_10m"),
            .init(name: "hourly", value: "temperature_2m,weather_code,precipitation_probability"),
            .init(name: "daily", value: "weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,precipitation_probability_max"),
            .init(name: "timezone", value: "auto"), .init(name: "forecast_days", value: "10")
        ]
        guard let url = c?.url else { throw WeatherServiceError.invalidURL }
        let (data, response) = try await session.data(from: url)
        guard let http = response as? HTTPURLResponse, 200..<300 ~= http.statusCode else { throw WeatherServiceError.invalidResponse }
        return try JSONDecoder().decode(WeatherResponse.self, from: data)
    }
    func searchPlaces(query: String) async throws -> [PlaceResult] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines); guard q.count >= 2 else { return [] }
        var c = URLComponents(string: "https://geocoding-api.open-meteo.com/v1/search")
        c?.queryItems = [.init(name: "name", value: q), .init(name: "count", value: "8"), .init(name: "language", value: "ru"), .init(name: "format", value: "json")]
        guard let url = c?.url else { throw WeatherServiceError.invalidURL }
        let (data, response) = try await session.data(from: url)
        guard let http = response as? HTTPURLResponse, 200..<300 ~= http.statusCode else { throw WeatherServiceError.invalidResponse }
        return try JSONDecoder().decode(PlaceSearchResponse.self, from: data).results ?? []
    }
}
